import{_ as o,C as n,o as l,c as h,a2 as a,j as i,G as t}from"./chunks/framework.BgSoyxN5.js";const b=JSON.parse('{"title":"Market Regime: Which Conditions You Are In, Not What Just Happened | TickerForge","description":"Five named market conditions, computed the same way every week and recorded every time they change. What a regime read answers that a market news feed cannot, and how to publish it in your own channel.","frontmatter":{"title":"Market Regime: Which Conditions You Are In, Not What Just Happened | TickerForge","description":"Five named market conditions, computed the same way every week and recorded every time they change. What a regime read answers that a market news feed cannot, and how to publish it in your own channel.","aside":false,"locale":"en","alternateLocales":{"en":"/market-intelligence/market-regime","ru":"/ru/market-intelligence/market-regime"},"pageClass":"partners-page"},"headers":[],"relativePath":"market-intelligence/market-regime.md","filePath":"market-intelligence/market-regime.md","lastUpdated":1788182993000}'),d={name:"market-intelligence/market-regime.md"},c={class:"partners-wide"},m={class:"partners-post-gallery"};function g(p,e,u,k,w,f){const r=n("PartnerPostImage"),s=n("PartnerChannelCta");return l(),h("div",null,[e[0]||(e[0]=a('<h1 id="market-regime" tabindex="-1">Market Regime <a class="header-anchor" href="#market-regime" aria-label="Permalink to &quot;Market Regime&quot;">​</a></h1><p>Five named conditions — Panic, Defensive, Recovery, Trend, Euphoria. One of them is true right now, and knowing which one changes how everything else should be read.</p><div class="partners-hero-actions"><a class="partners-button partners-button--primary" href="/market-widget">See the current regime</a><a class="partners-button partners-button--secondary" href="#publish">Publish it in your channel</a></div><p class="partners-locale-switch"><a href="/ru/market-intelligence/market-regime" hreflang="ru">Читать эту страницу на русском</a></p><p class="partners-backlink"><a href="/market-intelligence/">All market intelligence reads</a> · <a href="/market-intelligence/market-stress">Market Stress</a> · <a href="/market-intelligence/fear-and-greed">Fear &amp; Greed</a></p><h2 id="answers" tabindex="-1">The Question It Answers <a class="header-anchor" href="#answers" aria-label="Permalink to &quot;The Question It Answers {#answers}&quot;">​</a></h2><p><strong>&quot;Is this drop noise, or is it confirmation?&quot;</strong></p><p>The same 1% decline means opposite things in different conditions. Inside a Trend regime it is a pullback in a market with broad participation. Inside a Defensive one it is the market doing what a fragile market does. No headline can make that distinction, because a headline is about the 1%, not about the conditions around it.</p><h2 id="why" tabindex="-1">Why A State Read Beats A News Feed <a class="header-anchor" href="#why" aria-label="Permalink to &quot;Why A State Read Beats A News Feed {#why}&quot;">​</a></h2><div class="partners-wide partners-wide--compact"><ul class="partners-feature-list"><li><strong>It is a series, not a stream.</strong> The regime is one label that persists for weeks. A reader can follow &quot;Defensive → Recovery → Trend&quot; across months and see the shape of a cycle. A news feed hands them a different topic every morning and no thread between them.</li><li><strong>It changes rarely, and that is the point.</strong> Most days the answer is &quot;the same as yesterday&quot;. A read that changes constantly is not measuring a state, it is measuring noise.</li><li><strong>The change is announced separately.</strong> Both the daily snapshot and the weekly post always state the current regime, so a regime that just turned looks identical to one that has held for three weeks. A separate alert fires only on the days it actually changed — see the example below.</li><li><strong>It is recorded.</strong> Every regime read is stored with its date. Nobody has to take a channel&#39;s word for what it said last month.</li><li><strong>The rule is public.</strong> Cross-asset trend panel, macro score, ADX cross-validation — <a href="/methodology/decoding-market-regimes">the method is written down</a> and a reader can disagree with it on the merits.</li></ul></div><h2 id="example" tabindex="-1">What The Post Looks Like <a class="header-anchor" href="#example" aria-label="Permalink to &quot;What The Post Looks Like {#example}&quot;">​</a></h2>',11)),i("div",c,[i("div",m,[t(r,{src:"/partners/examples/daily-market-regime-sample.png",alt:"TickerForge Market Regime post: the current regime with equities, breadth and the macro risk layer",caption:"The recurring read — regime, panel, and what to watch."}),t(r,{src:"/partners/examples/market-regime-state-change-sample.png",alt:"TickerForge Market Regime State Change alert: the transition, what it means, bias and playbook",caption:"The state-change alert — published only on the weeks the regime turns."})])]),e[1]||(e[1]=a('<h2 id="method" tabindex="-1">How It Is Built <a class="header-anchor" href="#method" aria-label="Permalink to &quot;How It Is Built {#method}&quot;">​</a></h2><p>A cross-asset trend panel across equities, credit, rates, the dollar and volatility produces a macro score; the score maps to one of the five regimes and is cross-validated against trend strength so a single wobbling input cannot flip the label on its own.</p><p>Full write-up: <a href="/methodology/decoding-market-regimes">Decoding Market Regimes</a>.</p><h2 id="publish" tabindex="-1">Two Ways To Use It <a class="header-anchor" href="#publish" aria-label="Permalink to &quot;Two Ways To Use It {#publish}&quot;">​</a></h2><div class="partners-wide partners-wide--compact"><ul class="partners-feature-list"><li><strong>Read it.</strong> The weekly regime post and the daily snapshot run on the TickerForge public channel, and the full market dashboard lives in the bot.</li><li><strong>Publish it.</strong> An approved partner generates the same post with their own tracked link inside it, in English or Russian, in one tap — including the state-change alert, which the Cabinet refuses to generate on a week the regime did not actually turn. See <a href="/partners/market-news">Market News partners</a>.</li></ul></div>',5)),t(s),e[2]||(e[2]=a('<p>A regime is context, not a signal. It does not say what to buy, what to sell, or when. TickerForge is educational decision-support software, not financial advice.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/market-intelligence/">All market intelligence reads</a></li><li><a href="/market-widget">Live market regime widget</a></li><li><a href="/methodology/decoding-market-regimes">Decoding market regimes — methodology</a></li><li><a href="/partners/market-news">Market news partner program</a></li></ul>',3))])}const _=o(d,[["render",g]]);export{b as __pageData,_ as default};
